def semver_sort(versions):
    def parse_version(v):
        # Split by '+' to separate build metadata
        v_without_build = v.split('+')[0]

        # Split by '-' to separate pre-release
        if '-' in v_without_build:
            version_part, prerelease_part = v_without_build.split('-', 1)
        else:
            version_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part is not None:
            prerelease_identifiers = prerelease_part.split('.')
            # Convert to comparable form: (is_numeric, numeric_value_or_string)
            parsed_identifiers = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    parsed_identifiers.append((0, int(identifier)))
                else:
                    parsed_identifiers.append((1, identifier))
            prerelease_key = tuple(parsed_identifiers)
        else:
            prerelease_key = None

        return (major, minor, patch, prerelease_key)

    def sort_key(v):
        major, minor, patch, prerelease_key = parse_version(v)

        # For sorting: version with pre-release comes before version without
        # If prerelease_key is None, it should sort after (0,) so use (1,) as marker
        if prerelease_key is None:
            prerelease_sort = (1,)
        else:
            prerelease_sort = (0, prerelease_key)

        return (major, minor, patch, prerelease_sort)

    # Stable sort to maintain input order for equal versions
    return sorted(versions, key=sort_key)

